#include <cstdint>
#include <iostream>
#include <map>

struct Order {
    int id = 0;
    bool buy = false;   // a bid when true, an ask (an offer to sell) when false
    int64_t price = 0;  // in ticks of $0.01, so 10050 is $100.50
    int64_t qty = 0;
};

struct Level {
    int64_t qty = 0;  // everything resting at this price
    int orders = 0;
};

using Levels = std::map<int64_t, Level>;  // price to level, lowest price first

class OrderBook {
public:
    static constexpr int64_t kNone = -1;  // the best price of an empty side

    void add(const Order& o) {
        Level& level = (o.buy ? bids_ : asks_)[o.price];  // a new price makes a new level
        level.qty += o.qty;
        ++level.orders;
    }

    int64_t best_bid() const { return bids_.empty() ? kNone : bids_.rbegin()->first; }
    int64_t best_ask() const { return asks_.empty() ? kNone : asks_.begin()->first; }

    void print() const {  // the ladder: highest price at the top
        for (const Levels* side : {&asks_, &bids_}) {
            for (auto level = side->rbegin(); level != side->rend(); ++level) {
                std::cout << (side == &asks_ ? "ask " : "bid ") << level->first << " qty "
                          << level->second.qty << " orders " << level->second.orders << '\n';
            }
        }
    }

private:
    Levels bids_;  // the best bid is the highest price, the last key
    Levels asks_;  // the best ask is the lowest price, the first key
};

int main() {
    OrderBook book;
    char side = 0;
    Order o;
    while (std::cin >> side >> o.id >> o.price >> o.qty) {
        o.buy = side == 'B';
        book.add(o);
    }
    book.print();
    std::cout << "best bid " << book.best_bid() << ", best ask " << book.best_ask()
              << ", spread " << book.best_ask() - book.best_bid() << " ticks\n";
    return 0;
}

