#include <algorithm>
#include <cstdint>
#include <deque>
#include <iostream>
#include <iterator>
#include <map>

struct Order {
    int id = 0;
    bool buy = false;
    int64_t price = 0;  // ticks
    int64_t qty = 0;
};

using Levels = std::map<int64_t, std::deque<Order>>;  // price to orders, oldest first

class OrderBook {
public:
    void add(Order o) {
        Levels& other = o.buy ? asks_ : bids_;
        while (o.qty > 0 && !other.empty()) {
            auto best = o.buy ? other.begin() : std::prev(other.end());  // lowest ask, highest bid
            if (o.buy ? best->first > o.price : best->first < o.price) {
                break;  // the best price no longer crosses
            }
            Order& maker = best->second.front();  // the oldest order at that price
            const int64_t fill = std::min(o.qty, maker.qty);
            std::cout << "trade " << fill << " @ " << best->first << " taker " << o.id << " maker " << maker.id << '\n';
            o.qty -= fill;
            maker.qty -= fill;
            if (maker.qty == 0) {
                best->second.pop_front();
            }
            if (best->second.empty()) {
                other.erase(best);
            }
        }
        if (o.qty > 0) {
            (o.buy ? bids_ : asks_)[o.price].push_back(o);  // the rest waits at the back
        }
    }

    void print() const {
        for (const Levels* side : {&asks_, &bids_}) {
            for (auto level = side->rbegin(); level != side->rend(); ++level) {
                std::cout << (side == &asks_ ? "ask " : "bid ") << level->first;
                for (const Order& o : level->second) {
                    std::cout << ' ' << o.id << ':' << o.qty;
                }
                std::cout << '\n';
            }
        }
    }

private:
    Levels bids_;
    Levels asks_;
};

int main() {
    OrderBook book;
    char side = 0;
    Order o;
    while (std::cin >> side >> o.id >> o.price >> o.qty) {
        o.buy = side == 'B';
        book.add(o);
    }
    book.print();
    return 0;
}

