#include <cstdint>
#include <iostream>
#include <list>
#include <map>
#include <unordered_map>

struct Order {
    int id = 0;
    bool buy = false;
    int64_t price = 0;  // ticks
    int64_t qty = 0;
};

using Levels = std::map<int64_t, std::list<Order>>;  // price to orders, oldest first

class OrderBook {
public:
    void add(const Order& o) {
        std::list<Order>& queue = (o.buy ? bids_ : asks_)[o.price];
        where_[o.id] = queue.insert(queue.end(), o);  // the id now leads to its node
    }

    void modify(int id, int64_t price, int64_t qty) {
        auto found = where_.find(id);
        if (found == where_.end()) {
            return;  // filled already, or never seen
        }
        auto order = found->second;
        if (price == order->price && qty <= order->qty) {
            order->qty = qty;  // smaller at the same price: keeps its place
            return;
        }
        Order moved = *order;
        moved.price = price;
        moved.qty = qty;
        Levels& side = order->buy ? bids_ : asks_;
        auto level = side.find(order->price);
        level->second.erase(order);
        if (level->second.empty()) {
            side.erase(level);
        }
        add(moved);  // a new price or more size: the back of the line
    }

    void print() const {
        for (const Levels* side : {&asks_, &bids_}) {
            for (auto level = side->rbegin(); level != side->rend(); ++level) {
                std::cout << (side == &asks_ ? "ask " : "bid ") << level->first;
                for (const Order& o : level->second) {
                    std::cout << ' ' << o.id << ':' << o.qty;
                }
                std::cout << '\n';
            }
        }
    }

private:
    Levels bids_;
    Levels asks_;
    std::unordered_map<int, std::list<Order>::iterator> where_;  // id to its node
};

