steps.body:
Your firm's copy of the exchange's book is rebuilt from its feed: add, cancel, and execute messages, each naming an order id. The exchange already matched, so the copy never does. It needs each level's total and each order's price and size, and it must keep up with every message on every symbol, so it can't allocate.

A `std::map` allocates a node every time a price level appears, and levels come and go all day as prices move:

```cpp harness
#include <bits/stdc++.h>

long g_allocs = 0;
void* operator new(std::size_t n) {
    ++g_allocs;
    if (void* p = std::malloc(n)) {
        return p;
    }
    throw std::bad_alloc();
}
void operator delete(void* p) noexcept {
    std::free(p);
}

int main() {
    {{code}}
    return 0;
}
```

```cpp
std::map<int64_t, int64_t> asks;  // price to quantity
for (int i = 0; i < 1000; ++i) {
    asks[10051] += 10;  // an order makes a new level
    asks.erase(10051);  // it trades, and the level is gone
}
std::cout << g_allocs << '\n';  // 1000
```

The array book allocates three vectors once, in its constructor:

- `bids_[p]` and `asks_[p]` hold the quantity resting at tick `p`, over a band of 16384 ticks.
- `orders_[id]` holds each order's side, price, and quantity. These ids are small, so they index the vector. A real feed's 64-bit ids would go through an open-addressing map like the one in *Hash Maps: unordered_map Inside and Open Addressing*, with tombstones for erases.
- `best_bid_` and `best_ask_` are cached, so reading the BBO is O(1).

A modify here is a cancel and then an add, since priority is the exchange's business and the copy only keeps totals:

```cpp harness
#include <bits/stdc++.h>

struct Order {
    int64_t qty = 0;  // 0 once it leaves the book
    int price = 0;    // ticks, and the index of its level
    bool buy = false;
};

class OrderBook {
public:
    OrderBook(int ticks, int ids) : bids_(ticks), asks_(ticks), orders_(ids) {}  // all the allocating

    void add(int id, bool buy, int price, int64_t qty) {
        orders_[id] = Order{qty, price, buy};
        (buy ? bids_ : asks_)[price] += qty;
        int& best = buy ? best_bid_ : best_ask_;
        if (best < 0 || (buy ? price > best : price < best)) {
            best = price;  // a better price: O(1)
        }
    }

    void cancel(int id) { take(orders_[id], orders_[id].qty); }

    {{code}}

    int best_bid() const { return best_bid_; }  // -1 when there are no bids
    int best_ask() const { return best_ask_; }  // -1 when there are no asks

private:
    void take(Order& o, int64_t qty) {  // removes qty of a resting order
        std::vector<int64_t>& side = o.buy ? bids_ : asks_;
        side[o.price] -= qty;
        o.qty -= qty;
        int& best = o.buy ? best_bid_ : best_ask_;
        while (best >= 0 && side[best] == 0) {  // the best level emptied: walk outward
            best = o.buy ? best - 1 : (best + 1 < static_cast<int>(side.size()) ? best + 1 : -1);
        }
    }

    std::vector<int64_t> bids_;  // resting quantity at each tick
    std::vector<int64_t> asks_;
    std::vector<Order> orders_;  // one slot per order id
    int best_bid_ = -1;
    int best_ask_ = -1;
};

int main() {
    OrderBook book(1 << 14, 1 << 10);
    book.add(1, true, 10049, 30);
    book.add(2, true, 10050, 10);
    std::cout << book.best_bid() << '\n';
    book.modify(2, 10048, 10);
    std::cout << book.best_bid() << '\n';
    return 0;
}
```

```cpp
