        orders_[id] = Order{qty, price, buy};
        (buy ? bids_ : asks_)[price] += qty;
        int& best = buy ? best_bid_ : best_ask_;
        if (best < 0 || (buy ? price > best : price < best)) {
            best = price;  // a better price: O(1)
        }
    }

